<?php
namespace Modules\Ran\Http\Controllers;use Modules\Ran\Entities\{Purchase,SupplierPayment};use Modules\Ran\Http\Requests\SupplierPaymentRequest;use Modules\Ran\Integrations\{FinanceIntegrationService,SupplierIntegrationService};use Modules\Ran\Services\SupplierPaymentService;
class SupplierPaymentController extends RanController{public function __construct(private SupplierPaymentService $service,private SupplierIntegrationService $suppliers,private FinanceIntegrationService $finance){}public function index(){return view('ran::supplier-payments.index',['payments'=>SupplierPayment::query()->with('supplier','purchase')->latest('payment_date')->paginate(25)]);}public function create(){return view('ran::supplier-payments.form',array_merge($this->pageOptions(),['suppliers'=>$this->suppliers->dropdown(),'accounts'=>$this->finance->dropdown(),'purchases'=>Purchase::query()->where('balance_amount','>',0)->orderByDesc('purchase_date')->get()]));}public function store(SupplierPaymentRequest $r){$this->service->create($r->validated());return $this->success('Supplier payment posted.','ran.supplier-payments.index');}}
